// n8n's Webhook node wraps the request as { headers, params, query, body }.
// Accept either that wrapper or a direct payload.
const raw = $input.first().json;
const item = raw && raw.body && typeof raw.body === 'object' ? raw.body : raw;

const required = [
  'event',
  'notificationId',
  'orderNumber',
  'customerName',
  'customerEmail',
  'destinationName',
  'packageName',
  'packageDataSnapshot',
  'totalIdr',
  'paidAt',
];

const missing = required.filter((key) => item[key] === undefined || item[key] === null || item[key] === '');

if (missing.length > 0) {
  throw new Error('invalid_payload: missing ' + missing.join(','));
}

if (item.event !== 'order.paid') {
  throw new Error('invalid_event: ' + String(item.event));
}

// Order number shape: RML- followed by six uppercase letters or digits.
const orderNumber = String(item.orderNumber);
const orderBody = orderNumber.slice(4);
const isUpperAlnum = (ch) => (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9');

if (orderNumber.slice(0, 4) !== 'RML-' || orderBody.length !== 6 || !orderBody.split('').every(isUpperAlnum)) {
  throw new Error('invalid_payload: orderNumber');
}

if (!Number.isInteger(item.totalIdr) || item.totalIdr <= 0) {
  throw new Error('invalid_payload: totalIdr');
}

// paidAt is written by the database as a UTC ISO instant with millisecond precision.
// Round-tripping through Date proves it is a real instant AND in canonical form,
// without relying on a regular expression or on locale data.
const paidAtMs = Date.parse(String(item.paidAt));
const paidAtCanonical = Number.isNaN(paidAtMs) ? null : new Date(paidAtMs).toISOString();

if (paidAtCanonical !== item.paidAt) {
  throw new Error('invalid_payload: paidAt');
}

// Deterministic WIB (UTC+7): shift the instant, then read the UTC parts.
// No Intl, no toLocaleString, no ICU data. Day, month, and year rollover follow from the
// shifted instant.
const WIB_OFFSET_MS = 7 * 60 * 60 * 1000;
const wib = new Date(paidAtMs + WIB_OFFSET_MS);
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const pad = (value) => String(value).padStart(2, '0');
const paidAtWib =
  wib.getUTCDate() +
  ' ' +
  MONTHS[wib.getUTCMonth()] +
  ' ' +
  wib.getUTCFullYear() +
  ', ' +
  pad(wib.getUTCHours()) +
  ':' +
  pad(wib.getUTCMinutes());

const escape = (value) =>
  String(value)
    .split('&').join('&amp;')
    .split('<').join('&lt;')
    .split('>').join('&gt;')
    .split('"').join('&quot;');

const groupThousands = (value) => {
  let digits = String(value);
  let out = '';

  while (digits.length > 3) {
    out = '.' + digits.slice(-3) + out;
    digits = digits.slice(0, -3);
  }

  return digits + out;
};

const totalIdr = 'Rp ' + groupThousands(item.totalIdr);

const html = [
  '<h2>Your Roamly order is confirmed</h2>',
  '<p>Hi ' + escape(item.customerName) + ',</p>',
  '<p>We received your payment for <strong>' + escape(item.packageName) + '</strong>',
  ' (' + escape(item.packageDataSnapshot) + ') for ' + escape(item.destinationName) + '.</p>',
  '<table cellpadding="6" style="border-collapse:collapse">',
  '  <tr><td>Order</td><td><strong>' + escape(item.orderNumber) + '</strong></td></tr>',
  '  <tr><td>Total</td><td>' + escape(totalIdr) + '</td></tr>',
  '  <tr><td>Paid</td><td>' + escape(paidAtWib) + ' WIB</td></tr>',
  '</table>',
  '<p>Keep this email as your receipt. To view the order, use the link you received at checkout.</p>',
  '<p style="color:#5a6b7a;font-size:12px">Reference: ' + escape(item.notificationId) + '</p>',
].join(String.fromCharCode(10));

return [
  {
    json: {
      notificationId: item.notificationId,
      orderNumber: item.orderNumber,
      to: item.customerEmail,
      subject: 'Roamly order ' + item.orderNumber + ' confirmed',
      html,
    },
  },
];
